function renderSeries(){const s=seriesState.active,el=$("#seriesSummary");if(!s){el.className="series-empty";el.textContent="팀 구성을 확정하면 세트 이벤트가 시작됩니다.";return}const sc=seriesScore(s),pog=[...s.blue,...s.red].find(p=>String(p.id)===String(s.pogId)),winner=s.finished?seriesTeamName(s,s.finalWinner):"";el.className="series-card";el.innerHTML=`<div class="series-head"><div><b class="captain-score">${seriesTeamName(s,"BLUE")} ${sc.blue} : ${sc.red} ${seriesTeamName(s,"RED")}</b><small>${s.finished?`${winner} 최종 승리 · POG ${pog?.name||"-"}`:`${s.sets.filter(x=>x.imported).length}세트 완료 · 최대 5세트`}</small></div><div class="series-actions"><button id="manageSeries">${s.finished?"결과 보기":"이벤트 진행"}</button></div></div>`;$("#manageSeries").onclick=()=>openSeries(s)}
