function renderSeriesDialog(s=seriesState.active){if(!s)return;const sc=seriesScore(s),all=[...s.blue,...s.red],pog=all.find(p=>String(p.id)===String(s.pogId));if(s.finished){$("#seriesDialogContent").innerHTML=`<h2>내전 최종 결과</h2><div class="captain-final"><div><b>${seriesTeamName(s,"BLUE")}</b><span>${sc.blue}</span></div><i>:</i><div><span>${sc.red}</span><b>${seriesTeamName(s,"RED")}</b></div></div><div class="series-result"><b>${seriesTeamName(s,s.finalWinner)} 최종 승리</b><br>🏆 POG · ${pog?.name||"-"} <small>(${s.pogScore||0}점)</small></div><div class="completed-sets">${s.sets.filter(x=>x.imported).map(set=>completedSetHtml(s,set)).join("")}</div>`;return}$("#seriesDialogContent").innerHTML=`<h2>세트 이벤트 진행</h2><div class="event-teams"><div class="event-team"><b>${seriesTeamName(s,"BLUE")} · ${sc.blue}승</b><p>${s.blue.map(p=>`${p.id===s.blueCaptainId?"👑 ":""}${ROLE_KO[p.role]} ${p.name}`).join("<br>")}</p></div><div class="event-vs">VS</div><div class="event-team red"><b>${seriesTeamName(s,"RED")} · ${sc.red}승</b><p>${s.red.map(p=>`${p.name} ${ROLE_KO[p.role]}${p.id===s.redCaptainId?" 👑":""}`).join("<br>")}</p></div></div><div class="set-list">${s.sets.map((set,i)=>`<div class="set-row" data-set="${i}"><b>${set.number} SET</b><input class="set-game-id" inputmode="numeric" placeholder="게임 ID" value="${set.gameId||""}" ${set.imported?"disabled":""}><span class="set-result">${set.imported?`${seriesTeamName(s,set.winner)} 승${set.rolesConfirmed?" · 포지션 확정":""}`:"자동 판정"}</span><button class="save-set" ${set.imported?"disabled":""}>${set.imported?"저장됨":"ID 저장"}</button></div>`).join("")}</div><div class="event-controls"><button class="add-set" ${s.sets.length>=5?"disabled":""}>+ 다음 세트 추가</button></div><div class="pog-guide">게임 ID를 저장하면 확정한 팀 구성으로 10명의 포지션을 자동 매칭합니다. POG는 최종 승리팀에서 경기 지표로 선정됩니다.</div><div class="event-controls"><button class="finish-series">최종 결과 확정 및 POG 선정</button></div>`}
