function detectSeriesWinner(match,s){const mapped=match.participants.map(mp=>({mp,player:findRegistered(mp)})).filter(x=>x.player),blueIds=new Set(s.blue.map(p=>p.id)),redIds=new Set(s.red.map(p=>p.id));const teamScores=[100,200].map(teamId=>{const members=mapped.filter(x=>x.mp.teamId===teamId);return {teamId,blue:members.filter(x=>blueIds.has(x.player.id)).length,red:members.filter(x=>redIds.has(x.player.id)).length,won:Boolean(members[0]?.mp.win)}});const blueSide=[...teamScores].sort((a,b)=>(b.blue-b.red)-(a.blue-a.red))[0];if(!blueSide||blueSide.blue===blueSide.red)throw new Error("플레이 계정 연결이 부족해 이벤트 팀을 판별할 수 없습니다.");return blueSide.won?"BLUE":"RED"}
