function calculatePOG(s,winner){const roster=winner==="BLUE"?s.blue:s.red,ids=new Set(roster.map(p=>p.id)),scores=new Map();for(const set of s.sets.filter(x=>x.imported)){const match=internalMatches.find(m=>m.gameId===set.gameId);if(!match)continue;for(const mp of match.participants){const player=findRegistered(mp);if(!player||!ids.has(player.id))continue;const team=match.participants.filter(x=>x.teamId===mp.teamId),sum=key=>team.reduce((a,x)=>a+(Number(x[key])||0),0),share=(value,total)=>Math.min(1.5,(total?value/total:0)/.2)/1.5,kda=(mp.kills+mp.assists)/Math.max(1,mp.deaths),kp=Math.min(1,(mp.kills+mp.assists)/Math.max(1,sum("kills"))),points=kp*30+share(mp.damage||0,sum("damage"))*25+Math.min(1,kda/8)*20+share(mp.vision||0,sum("vision"))*15+share(mp.gold||0,sum("gold"))*10,current=scores.get(player.id)||{total:0,games:0};current.total+=points;current.games++;scores.set(player.id,current)}}const ranked=[...scores].map(([id,v])=>({id,score:Number((v.total/v.games).toFixed(1))})).sort((a,b)=>b.score-a.score);if(!ranked.length)throw new Error("계정 연결이 부족해 POG를 계산할 수 없습니다.");return ranked[0]}
