function renderLeaderboard(){if(!$("#leaderboard"))return;const activePlayers=players.filter(p=>!p.archived),pogCounts=new Map();for(const series of seriesState.history.filter(s=>s.finished&&s.pogId))pogCounts.set(String(series.pogId),(pogCounts.get(String(series.pogId))||0)+1);const stats=activePlayers.map(p=>{const games=playerInternalGames(p),sum=key=>games.reduce((total,x)=>total+(Number(x.mp[key])||0),0),seconds=games.reduce((total,x)=>total+(Number(x.match.duration)||0),0),wins=games.filter(x=>x.mp.win).length,deaths=sum("deaths");return {id:p.id,name:p.name,color:p.color,games:games.length,wins,winRate:games.length?wins/games.length:0,kda:games.length?(sum("kills")+sum("assists"))/Math.max(1,deaths):0,dps:seconds?sum("damage")/seconds:0,power:score(p,p.role),pog:pogCounts.get(String(p.id))||0,role:ROLE_KO[p.role]||p.role}}),by=(key,filter=()=>true)=>stats.filter(filter).sort((a,b)=>b[key]-a[key]||b.games-a.games||a.name.localeCompare(b.name,"ko"));leaderboardCard("#powerLeaderboard","롤력 순위","솔랭 추정과 내전 보정을 합산",by("power"),value=>Math.round(value).toLocaleString());leaderboardCard("#pogLeaderboard","POG 순위","완료된 시리즈 최우수 선수",by("pog",x=>x.pog>0),(value,row)=>`${value}회`);leaderboardCard("#dpsLeaderboard","DPM 순위","내전 총 피해량 ÷ 실제 플레이 시간(분)",by("dps",x=>x.games>0),value=>`${Math.round(value*60).toLocaleString()} <small>분당 피해량</small>`);leaderboardCard("#kdaLeaderboard","KDA 순위","내전 전체 (킬+어시스트) ÷ 데스",by("kda",x=>x.games>0),value=>value.toFixed(2));leaderboardCard("#winLeaderboard","승률 순위","최소 3경기 참가자",by("winRate",x=>x.games>=3),(value,row)=>`${Math.round(value*100)}% <small>${row.wins}승</small>`);leaderboardCard("#gamesLeaderboard","내전 참여 순위","누적 집계 경기 수",by("games",x=>x.games>0),value=>`${value}경기`);$("#leaderboardSummary").innerHTML=`<span>누적 경기 <b>${internalMatches.length}</b></span><span>집계 선수 <b>${stats.filter(x=>x.games).length}</b></span><span>완료 시리즈 <b>${seriesState.history.filter(s=>s.finished).length}</b></span>`}
