function liveTeamSlot(element){const team=element?.closest("#blueTeam,#redTeam");if(!team)return null;const rows=[...team.querySelectorAll(":scope > .member")],row=element.closest(".member"),index=rows.indexOf(row);if(index<0||!ROLES[index])return null;return {side:team.id==="blueTeam"?"BLUE":"RED",role:ROLES[index]}}
function enhanceLiveTeamEditor(){document.querySelectorAll("#blueTeam > .member,#redTeam > .member").forEach(row=>{row.classList.add("live-team-slot");row.title="포지션명을 끌어 다른 자리와 교환";const lane=row.querySelector(".lane");if(lane){lane.draggable=true;lane.classList.add("lane-drag-handle");lane.title="끌어서 맞라인 또는 포지션 교환";lane.setAttribute("aria-label",`${lane.textContent} 포지션 이동`)}})}
function swapLiveTeamSlots(from,to){if(!current||!from||!to||(from.side===to.side&&from.role===to.role))return;const slots=[...current.blue.members.map(p=>({side:"BLUE",role:p.assigned,player:players.find(x=>String(x.id)===String(p.id))||p})),...current.red.members.map(p=>({side:"RED",role:p.assigned,player:players.find(x=>String(x.id)===String(p.id))||p}))],source=slots.find(x=>x.side===from.side&&x.role===from.role),target=slots.find(x=>x.side===to.side&&x.role===to.role);if(!source||!target)return;[source.player,target.player]=[target.player,source.player];current=candidateFromSlots(slots);if(teamAlternatives.length)teamAlternatives[alternativeIndex]=current;else{teamAlternatives=[current];alternativeIndex=0}renderTeams();toast(`${ROLE_KO[from.role]} ↔ ${ROLE_KO[to.role]} 포지션을 교환했습니다.`)}
const liveTeamObserver=new MutationObserver(enhanceLiveTeamEditor);["blueTeam","redTeam"].forEach(id=>{const team=document.getElementById(id);if(team)liveTeamObserver.observe(team,{childList:true})});enhanceLiveTeamEditor();
document.addEventListener("dragstart",event=>{const handle=event.target.closest(".lane-drag-handle");if(!handle)return;liveTeamDragSource=liveTeamSlot(handle);event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",JSON.stringify(liveTeamDragSource));handle.closest(".member")?.classList.add("dragging")});
document.addEventListener("dragover",event=>{const row=event.target.closest("#blueTeam > .member,#redTeam > .member");if(!row||!liveTeamDragSource)return;event.preventDefault();event.dataTransfer.dropEffect="move";document.querySelectorAll(".live-team-slot.drag-target").forEach(x=>x.classList.remove("drag-target"));row.classList.add("drag-target")});
document.addEventListener("drop",event=>{const row=event.target.closest("#blueTeam > .member,#redTeam > .member");if(!row||!liveTeamDragSource)return;event.preventDefault();const target=liveTeamSlot(row),source=liveTeamDragSource;liveTeamDragSource=null;document.querySelectorAll(".live-team-slot.drag-target,.live-team-slot.dragging").forEach(x=>x.classList.remove("drag-target","dragging"));swapLiveTeamSlots(source,target)});
document.addEventListener("dragend",()=>{liveTeamDragSource=null;document.querySelectorAll(".live-team-slot.drag-target,.live-team-slot.dragging").forEach(x=>x.classList.remove("drag-target","dragging"))});
updateAliasCount();
renderSeries();
syncAppState();
syncServerMatches();
setTimeout(renderLeaderboard,0);
